-- Modify "order_items" table
ALTER TABLE "order_items" ADD COLUMN "delivery_kind" character varying NOT NULL DEFAULT 'card', ADD COLUMN "sms_product" jsonb NULL, ADD COLUMN "sms_purchase_snapshot" text NULL;
-- Modify "products" table
ALTER TABLE "products" ADD COLUMN "delivery_kind" character varying NOT NULL DEFAULT 'card', ADD COLUMN "sms_product" jsonb NULL;
-- Create "sms_intents" table
CREATE TABLE "sms_intents" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "order_id" bigint NOT NULL, "order_item_id" bigint NOT NULL, "user_id" bigint NOT NULL, "connection_id" bigint NOT NULL, "connection_identity" character varying NOT NULL, "request_no" character varying NOT NULL, "request_json" text NOT NULL, "request_hash" character varying NOT NULL, "upstream_order_id" character varying NULL, "phase" character varying NOT NULL DEFAULT 'purchase', "state" character varying NOT NULL DEFAULT 'allocating', "session_id" character varying NOT NULL DEFAULT '', "version" bigint NOT NULL DEFAULT 0, "sms_revision" bigint NOT NULL DEFAULT 0, "snapshot_cipher" bytea NULL, "received" boolean NOT NULL DEFAULT false, "can_cancel" boolean NOT NULL DEFAULT false, "can_finish" boolean NOT NULL DEFAULT false, "charged_amount" bigint NOT NULL DEFAULT 0, "settlement_state" character varying NOT NULL DEFAULT '', "refunded_amount" bigint NOT NULL DEFAULT 0, "refund_reference" character varying NOT NULL DEFAULT '', "rejected_receipt" boolean NOT NULL DEFAULT false, "retail_refund_state" character varying NOT NULL DEFAULT 'none', "refund_id" bigint NOT NULL DEFAULT 0, "next_run_at" bigint NOT NULL DEFAULT 0, "lease_until" bigint NOT NULL DEFAULT 0, "lease_token" character varying NOT NULL DEFAULT '', "attempts" bigint NOT NULL DEFAULT 0, "last_error" character varying NOT NULL DEFAULT '', PRIMARY KEY ("id"));
-- Create index "smsintent_connection_id_upstream_order_id" to table: "sms_intents"
CREATE UNIQUE INDEX "smsintent_connection_id_upstream_order_id" ON "sms_intents" ("connection_id", "upstream_order_id");
-- Create index "smsintent_order_item_id" to table: "sms_intents"
CREATE UNIQUE INDEX "smsintent_order_item_id" ON "sms_intents" ("order_item_id");
-- Create index "smsintent_phase_next_run_at_lease_until" to table: "sms_intents"
CREATE INDEX "smsintent_phase_next_run_at_lease_until" ON "sms_intents" ("phase", "next_run_at", "lease_until");
-- Create index "smsintent_request_no" to table: "sms_intents"
CREATE UNIQUE INDEX "smsintent_request_no" ON "sms_intents" ("request_no");
-- Create index "smsintent_subsite_id_user_id_order_id" to table: "sms_intents"
CREATE INDEX "smsintent_subsite_id_user_id_order_id" ON "sms_intents" ("subsite_id", "user_id", "order_id");
-- Create "sms_operations" table
CREATE TABLE "sms_operations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "subsite_id" bigint NOT NULL DEFAULT 0, "intent_id" bigint NOT NULL, "operation_id" character varying NOT NULL, "action" character varying NOT NULL, "status" character varying NOT NULL DEFAULT 'pending', "error_code" character varying NOT NULL DEFAULT '', "attempts" bigint NOT NULL DEFAULT 0, PRIMARY KEY ("id"));
-- Create index "smsoperation_intent_id_status" to table: "sms_operations"
CREATE INDEX "smsoperation_intent_id_status" ON "sms_operations" ("intent_id", "status");
-- Create index "smsoperation_operation_id" to table: "sms_operations"
CREATE UNIQUE INDEX "smsoperation_operation_id" ON "sms_operations" ("operation_id");
